create table public.import_batches(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, marketplace text not null default 'SHOPEE', filename text not null, storage_path text, column_mapping jsonb not null default '{}', status text not null default 'PREVIEW' check(status in ('PREVIEW','VALIDATED','COMMITTED')), created_by uuid default auth.uid(), created_at timestamptz not null default now(), unique(workspace_id,id));
create table public.import_rows(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, batch_id uuid not null, row_number integer not null, raw_data jsonb not null, external_order_id text, external_item_id text, sku_id uuid, status text not null default 'NEW' check(status in ('NEW','DUPLICATE','UNMAPPED','ERROR','IMPORTED')), errors jsonb not null default '[]', sales_order_id uuid, unique(batch_id,row_number), foreign key(workspace_id,batch_id) references public.import_batches(workspace_id,id), foreign key(workspace_id,sku_id) references public.skus(workspace_id,id), foreign key(workspace_id,sales_order_id) references public.sales_orders(workspace_id,id));
create table public.reconciliation_links(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, sales_order_item_id uuid not null, procurement_item_id uuid not null, status text not null check(status in ('MATCHED','POTENTIAL_MATCH','UNMATCHED','DUPLICATE','CONFLICT')), active boolean not null default true, confirmed_by uuid, confirmed_at timestamptz, notes text, unique(sales_order_item_id,procurement_item_id), foreign key(workspace_id,sales_order_item_id) references public.sales_order_items(workspace_id,id), foreign key(workspace_id,procurement_item_id) references public.procurement_items(workspace_id,id));
create unique index reconciled_procurement_once on public.reconciliation_links(procurement_item_id) where status='MATCHED' and active;
create table public.financial_accounts(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, name text not null, account_type text not null check(account_type in ('BANK','MARKETPLACE_LIQUID','MARKETPLACE_PENDING','CASH','FX_ASSET','PREPAID_ASSET','LIABILITY','OTHER')), currency text not null default 'IDR' check(length(currency)=3), active boolean not null default true, unique(workspace_id,id));
create table public.financial_balance_snapshots(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, financial_account_id uuid not null, snapshot_date date not null, amount_original_currency numeric(24,8) not null check(amount_original_currency>=0), currency text not null default 'IDR', exchange_rate numeric(24,8) not null check(exchange_rate>0), amount_idr numeric(30,2) generated always as(round(amount_original_currency*exchange_rate,2)) stored, notes text, unique(financial_account_id,snapshot_date), foreign key(workspace_id,financial_account_id) references public.financial_accounts(workspace_id,id));
create table public.payments(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, customer_id uuid not null, invoice_id uuid not null, payment_date date not null default current_date, amount numeric(24,2) not null check(amount>0), payment_method text not null, financial_account_id uuid, reference text, notes text, status text not null default 'POSTED' check(status in ('POSTED','REVERSED')), created_by uuid default auth.uid(), foreign key(workspace_id,customer_id) references public.customers(workspace_id,id), foreign key(workspace_id,invoice_id) references public.invoices(workspace_id,id), foreign key(workspace_id,financial_account_id) references public.financial_accounts(workspace_id,id));
create table public.expenses(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, expense_date date not null, category text not null, amount numeric(24,2) not null check(amount>0), financial_account_id uuid, description text not null, reference text, status text not null default 'POSTED' check(status in ('POSTED','REVERSED')), created_by uuid default auth.uid(), foreign key(workspace_id,financial_account_id) references public.financial_accounts(workspace_id,id));
